import{_ as a,o,c as r,a8 as i}from"./chunks/framework.BppdKxCY.js";const u=JSON.parse('{"title":"EP.73 看不见的体验监控网","description":"","frontmatter":{},"headers":[],"relativePath":"comics/EP.73-web-performance-monitoring.md","filePath":"comics/EP.73-web-performance-monitoring.md","lastUpdated":1793706365000}'),l={name:"comics/EP.73-web-performance-monitoring.md"};function t(n,e,c,s,d,h){return o(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="ep-73-看不见的体验监控网" tabindex="-1">EP.73 看不见的体验监控网 <a class="header-anchor" href="#ep-73-看不见的体验监控网" aria-label="Permalink to &quot;EP.73 看不见的体验监控网&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../99-web-performance-monitoring">99-web-performance-monitoring.md</a>（99.1 Vitals / 99.2 错误捕获 / 99.3 APM 上报 / 99.4 指纹聚合）· 示例：<code>examples/99-01-web-performance-monitoring.ts</code></p></blockquote><h2 id="剧情回顾" tabindex="-1">剧情回顾 <a class="header-anchor" href="#剧情回顾" aria-label="Permalink to &quot;剧情回顾&quot;">​</a></h2><ul><li><strong>第 1 格</strong>：线上白屏，用户投诉才知道——没有错误监控。</li><li><strong>第 2 格</strong>：码叔揭秘错误捕获——onerror/unhandledrejection/资源错误三种方式。</li><li><strong>第 3 格</strong>：像素酱实证 APM 上报（采样+批量）与错误指纹聚合去重。</li><li><strong>第 4 格</strong>：码叔结案——健康评分与告警规则。</li></ul><h2 id="知识点拆解" tabindex="-1">知识点拆解 <a class="header-anchor" href="#知识点拆解" aria-label="Permalink to &quot;知识点拆解&quot;">​</a></h2><h3 id="第-1-格-·-没有监控的盲飞" tabindex="-1">第 1 格 · 没有监控的盲飞 <a class="header-anchor" href="#第-1-格-·-没有监控的盲飞" aria-label="Permalink to &quot;第 1 格 · 没有监控的盲飞&quot;">​</a></h3><ul><li>线上错误开发感知不到；</li><li>必须建立错误和性能监控才能闭环优化。</li></ul><h3 id="第-2-格-·-错误捕获" tabindex="-1">第 2 格 · 错误捕获 <a class="header-anchor" href="#第-2-格-·-错误捕获" aria-label="Permalink to &quot;第 2 格 · 错误捕获&quot;">​</a></h3><ul><li>JS 运行时：<code>window.onerror</code>；</li><li>Promise 拒绝：<code>unhandledrejection</code>；</li><li>资源加载：捕获阶段 <code>error</code> 事件；</li><li>React 渲染错误：Error Boundary。</li></ul><h3 id="第-3-格-·-apm-上报与指纹" tabindex="-1">第 3 格 · APM 上报与指纹 <a class="header-anchor" href="#第-3-格-·-apm-上报与指纹" aria-label="Permalink to &quot;第 3 格 · APM 上报与指纹&quot;">​</a></h3><ul><li>采样：错误全量、Vitals 采样；</li><li>批量：攒 N 条合并发；</li><li>指纹：message+stack 哈希，相同错误只更新计数。</li></ul><h3 id="第-4-格-·-健康评分与告警" tabindex="-1">第 4 格 · 健康评分与告警 <a class="header-anchor" href="#第-4-格-·-健康评分与告警" aria-label="Permalink to &quot;第 4 格 · 健康评分与告警&quot;">​</a></h3><ul><li>健康分 = Vitals(75%) + 错误率(25%)；</li><li>告警：错误率环比突增、LCP 超阈值，加抑制防风暴。</li></ul><h2 id="坑点清单" tabindex="-1">坑点清单 <a class="header-anchor" href="#坑点清单" aria-label="Permalink to &quot;坑点清单&quot;">​</a></h2><blockquote><p>🔗 正文对照：<a href="./../99-web-performance-monitoring#_99-7-本章避坑清单">《99.7 本章避坑清单》</a></p></blockquote><ol><li>上报风暴 → 采样+批量+限流；</li><li>数据丢失 → sendBeacon 或 fetch keepalive；</li><li>stack 看不懂 → 上传 sourcemap。</li></ol><h2 id="自测-3-题-含答案" tabindex="-1">自测 3 题（含答案） <a class="header-anchor" href="#自测-3-题-含答案" aria-label="Permalink to &quot;自测 3 题（含答案）&quot;">​</a></h2><ol><li>前端三类错误分别怎么捕获？——<strong>JS 错误用 window.onerror，Promise 用 unhandledrejection，资源错误用捕获阶段 error 事件</strong>。</li><li>APM 上报为什么要采样和批量？——<strong>防止上报风暴，降低服务器压力，采样减少数据量，批量减少请求数</strong>。</li><li>错误指纹有什么用？——<strong>把相同错误归并去重，避免同一错误存成千上万条</strong>。</li></ol>',18)])])}const b=a(l,[["render",t]]);export{u as __pageData,b as default};
